const SRC_NF_HEAD_APP_OF_DEAD_CONST_HEAD: &str = "def nf_head_app_of_dead_const_head (nm : Name) (hdef : Eq (OptionType KExpr) (defval_for (red_def the_red_env) nm) (OptionType.none KExpr)) (hrec : Eq (OptionType RecMeta) (recmeta_for (red_rec the_red_env) nm) (OptionType.none RecMeta)) (f : KExpr) (a : KExpr) (hh : Eq (OptionType Name) (kexpr_const_name (kapp_fn (KExpr.app f a))) (OptionType.some Name nm)) : nf_head (KExpr.app f a) := nf_head.neutral f a (iota_neutral_of_dead_const_head nm hdef hrec f hh) (iota_immune_of_dead_const_head nm hdef hrec (KExpr.app f a) hh)";

